# Шартты оператор if-else

`if` операторы белгілі бір шартта ғана кодты орындауға мүмкіндік береді.

**Синтаксис:**
```dart
if (шарт) {
  // шарт ақиқат болса, код орындалады
} else {
  // шарт жалған болса, код орындалады
}
```

**Салыстыру операторлары:**
- `==` - тең
- `!=` - тең емес
- `>` - үлкен
- `<` - кіші
- `>=` - үлкен немесе тең
- `<=` - кіші немесе тең

**Мысалда жасты өзгертіп көріңіз →**

pages.codeSnippet:
void main() {
  int age = 18;

  if (age >= 18) {
    print('Сіз кәмелетке толғансыз');
  } else {
    print('Сіз кәмелетке толмағансыз');
  }

  // else if арқылы көп шарттар
  int score = 85;

  if (score >= 90) {
    print('Баға: Өте жақсы!');
  } else if (score >= 75) {
    print('Баға: Жақсы!');
  } else if (score >= 60) {
    print('Баға: Қанағаттанарлық');
  } else {
    print('Баға: Жақсартуға тырысыңыз');
  }
}

void main() {
  int age = 20;
  bool hasLicense = true;

  // && операторы (ЖӘНЕ)
  if (age >= 18 && hasLicense) {
    print('Сіз машина айдай аласыз');
  }

  // || операторы (НЕМЕСЕ)
  String role = 'admin';
  if (role == 'admin' || role == 'moderator') {
    print('Сізде модератор құқықтары бар');
  }

  // ! операторы (ЖОҚ)
  bool isRaining = false;
  if (!isRaining) {
    print('Серуендеуге болады!');
  }

  // Операторларды біріктіру
  int temperature = 25;
  bool isSunny = true;

  if (temperature > 20 && temperature < 30 && isSunny) {
    print('Пикникке тамаша ауа райы!');
  }
}

void main() {
  int age = 20;

  // Қалыпты if-else
  String status1;
  if (age >= 18) {
    status1 = 'ересек';
  } else {
    status1 = 'бала';
  }
  print('Статус (if-else): $status1');

  // Тернарлық оператормен бірдей
  String status2 = age >= 18 ? 'ересек' : 'бала';
  print('Статус (тернарлық): $status2');

  // Ішкі тернарлық операторлар (абай болыңыз!)
  int score = 85;
  String grade = score >= 90 ? 'A' 
                : score >= 80 ? 'B'
                : score >= 70 ? 'C'
                : 'D';
  print('Баға: $grade');

  // Практикалық мысал
  int items = 3;
  print('Себетте $items ${items == 1 ? "тауар" : "тауар"}');
}

