# Коллекциялар бойынша итерация

**for-in** - тізім элементтерін айналдырудың ыңғайлы әдісі:
```dart
for (var элемент in коллекция) {
  // элементпен жұмыс
}
```

**forEach** - функциямен айналдыру әдісі:
```dart
коллекция.forEach((элемент) {
  // элементпен жұмыс
});
```

**Мысалдар →**

pages.codeSnippet:
void main() {
  List<String> fruits = ['Алма', 'Банан', 'Апельсин', 'Алмұрт'];

  // Индекспен қалыпты for
  print('Қалыпты for:');
  for (int i = 0; i < fruits.length; i++) {
    print('${i + 1}. ${fruits[i]}');
  }

  // for-in (оңайырақ!)
  print('\nFor-in:');
  for (var fruit in fruits) {
    print('- $fruit');
  }

  // forEach
  print('\nForEach:');
  fruits.forEach((fruit) {
    print('🍎 $fruit');
  });

  // Map айналдыру
  Map<String, int> scores = {
    'Әлия': 95,
    'Болат': 87,
    'Дәулет': 92,
  };

  print('\nНәтижелер:');
  scores.forEach((name, score) {
    print('$name: $score ұпай');
  });
}

void main() {
  // break - циклден шығу
  print('7 санын іздеу:');
  for (int i = 1; i <= 10; i++) {
    if (i == 7) {
      print('7 саны табылды!');
      break; // циклді үзу
    }
    print('$i тексерілуде...');
  }

  // continue - итерацияны өткізу
  print('\nТек жұп сандар:');
  for (int i = 1; i <= 10; i++) {
    if (i % 2 != 0) {
      continue; // тақ сандарды өткізу
    }
    print(i);
  }

  // Практикалық мысал
  print('\nТізімді сүзу:');
  List<int> numbers = [5, -3, 8, -1, 12, -7, 15];

  print('Оң сандар:');
  for (var num in numbers) {
    if (num < 0) continue; // теріс сандарды өткізу
    print(num);
  }
}

// Параметрлерсіз және қайтарусыз функция
void sayHello() {
  print('Сәлем!');
}

// Параметрлері бар функция
void greet(String name) {
