void main() {
  sayHello();

  greet('Әлия');
  greet('Болат');

  int sum = add(5, 3);
  print('5 + 3 = $sum');

  String name = getFullName('Иван', 'Иванов');
  print('Толық аты: $name');

  double area = calculateArea(5.0, 10.0);
  print('Аудан: $area');
}

// Міндетті позициялық параметрлер
void printSum(int a, int b) {
  print('$a + $b = ${a + b}');
}

// Міндетті емес позициялық параметрлер
String formatName(String firstName, [String? middleName, String? lastName]) {
  String result = firstName;
  if (middleName != null) result += ' $middleName';
  if (lastName != null) result += ' $lastName';
  return result;
}

// Атаулы параметрлер
void createUser({
  required String name,
  required int age,
  String? email,
  bool isPremium = false,
}) {
  print('Пайдаланушы: $name, $age жас');
  if (email != null) print('Email: $email');
  print('Премиум: ${isPremium ? "Иә" : "Жоқ"}');
}

// Әдепкі мәндер
int multiply(int a, [int b = 1]) {
  return a * b;
}

void main() {
  printSum(5, 3);

  print(formatName('Иван'));
  print(formatName('Иван', 'Петрович'));
  print(formatName('Иван', 'Петрович', 'Сидоров'));

  createUser(name: 'Әлия', age: 25);
  createUser(
    name: 'Болат',
    age: 30,
    email: 'bolat@example.com',
    isPremium: true,
  );

  print(multiply(5));    // 5 * 1 = 5
  print(multiply(5, 3)); // 5 * 3 = 15
}

// Қалыпты функция
int addNormal(int a, int b) {
  return a + b;
}

// Көрсеткі функция (бірдей)
int addArrow(int a, int b) => a + b;

// Басқа мысалдар
bool isEven(int number) => number % 2 == 0;

String greet(String name) => 'Сәлем, $name!';

double square(double x) => x * x;

bool isAdult(int age) => age >= 18;

String getStatus(int score) => score >= 60 ? 'Өтті' : 'Өтпеді';

void main() {
  print('Қалыпты: ${addNormal(5, 3)}');
  print('Көрсеткі: ${addArrow(5, 3)}');

  print('\n10 жұп па? ${isEven(10)}');
  print('7 жұп па? ${isEven(7)}');

  print('\n${greet("Әлия")}');

  print('\n5-тің квадраты: ${square(5)}');

  print('\n20 жас: ${isAdult(20) ? "ересек" : "бала"}');
  print('15 жас: ${isAdult(15) ? "ересек" : "бала"}');

  print('\n75 баға: ${getStatus(75)}');
  print('45 баға: ${getStatus(45)}');
}

void main() {
  // forEach-те анонимді функция
  List<int> numbers = [1, 2, 3, 4, 5];

  print('Квадраттар:');
  numbers.forEach((num) {
    print('$num² = ${num * num}');
  });

  // Қысқа түрі
  print('\nСандар:');
  numbers.forEach((num) => print(num));

  // Closure - функция айнымалыны есте сақтайды
  Function makeMultiplier(int multiplier) {
    return (int value) => value * multiplier;
  }

  var multiplyBy2 = makeMultiplier(2);
  var multiplyBy5 = makeMultiplier(5);

  print('\n10 × 2 = ${multiplyBy2(10)}');
  print('10 × 5 = ${multiplyBy5(10)}');

  // Практикалық мысал: санағыш
  Function makeCounter() {
    int count = 0;
    return () {
      count++;
      return count;
    };
  }

  var counter = makeCounter();
  print('\nСанағыш:');
  print(counter()); // 1
  print(counter()); // 2
  print(counter()); // 3
}

void main() {
  List<int> numbers = [1, 2, 3, 4, 5];

  // map - түрлендіру
  var doubled = numbers.map((n) => n * 2).toList();
  print('Екі еселенген: $doubled');

  // where - сүзу
  var evens = numbers.where((n) => n % 2 == 0).toList();
  print('Жұп сандар: $evens');

  // reduce - жинақтау
  var sum = numbers.reduce((a, b) => a + b);
  print('Қосынды: $sum');

  // Операцияларды біріктіру
  var result = numbers
      .where((n) => n > 2)        // сүзгі: > 2
      .map((n) => n * n)          // квадратқа шығару
      .toList();
  print('2-ден үлкен сандардың квадраттары: $result');

  // Мысал: функцияны қабылдайтын функция
  void executeOperation(int a, int b, Function operation) {
    var result = operation(a, b);
    print('Нәтиже: $result');
  }

  executeOperation(10, 5, (a, b) => a + b);  // Қосу
  executeOperation(10, 5, (a, b) => a - b);  // Азайту
  executeOperation(10, 5, (a, b) => a * b);  // Көбейту

  // Компараторымен сұрыптау
  List<String> fruits = ['банан', 'алма', 'апельсин', 'киви'];
  fruits.sort((a, b) => a.length.compareTo(b.length));
  print('\nҰзындығы бойынша: $fruits');
}

void main() {
  // Мысал 1: Функциядағы жергілікті айнымалылар
  void greet() {
    String message = 'Сәлем!'; // жергілікті айнымалы
    print(message);
  }

  greet();
  // print(message); // ҚАТЕ! message мұнда көрінбейді

  // Мысал 2: Блоктық көрініс аймағы
  int x = 10;

  if (x > 5) {
    int y = 20; // y тек if ішінде көрінеді
    print('x = $x, y = $y');
  }

  print('x = $x');
  // print('y = $y'); // ҚАТЕ! y мұнда көрінбейді

  // Мысал 3: Цикл өзінің аймағын жасайды
  for (int i = 0; i < 3; i++) {
    int counter = i * 2; // counter әр итерацияда жаңадан жасалады
    print('Итерация $i: counter = $counter');
  }

  // print(i); // ҚАТЕ! i цикл сыртында көрінбейді
  // print(counter); // ҚАТЕ! counter цикл сыртында көрінбейді

  // Мысал 4: Ішкі блоктар
  {
    int a = 1;
    print('Сыртқы блок: a = $a');

    {
      int b = 2;
      print('Ішкі блок: a = $a, b = $b'); // a көрінеді!
    }

    // print(b); // ҚАТЕ! b мұнда көрінбейді
  }
}

// Глобалды айнымалылар (функциялардан тыс)
String appName = 'Менің қолданбам';
const int maxAttempts = 3;
final double pi = 3.14159;

int globalCounter = 0; // өзгермелі глобалды айнымалы (сақ болыңыз!)

void main() {
  // Глобалды айнымалыларға қатынас
  print('Қолданба: $appName');
  print('Максимум әрекеттер: $maxAttempts');
  print('π саны: $pi');

  incrementCounter();
  incrementCounter();
  displayCounter();

  // Жергілікті айнымалы глобалдыны "көлеңкелейді"
  String appName = 'Жергілікті атау';
  print('Жергілікті айнымалы: $appName');
  // Глобалды appName әлі де қолжетімді, бірақ көлеңкеленген

  useConstants();
}

void incrementCounter() {
  globalCounter++; // глобалды айнымалыны өзгертеміз
  print('Санағыш арттырылды: $globalCounter');
}

void displayCounter() {
  print('Санағыштың ағымдағы мәні: $globalCounter');
}

void useConstants() {
  // Тұрақтылар глобалды пайдалану үшін қауіпсіз
  for (int i = 0; i < maxAttempts; i++) {
    print('Әрекет ${i + 1} / $maxAttempts');
  }

  double circleArea = pi * 5 * 5;
  print('Радиусы 5 шеңбердің ауданы: $circleArea');
}

// Глобалды айнымалы
int value = 100;

void main() {
  print('Глобалды value: $value');

  // Мысал 1: Параметрлер - жергілікті айнымалылар
  void printValue(int value) { // параметр глобалдыны көлеңкелейді
    print('Параметр value: $value');
    // Мұнда value - бұл параметр, глобалды айнымалы емес!
  }

  printValue(50);
  print('Глобалды value өзгермеді: $value');

  // Мысал 2: Көп деңгейлі көлеңкелеу
  void complexExample() {
    int value = 200; // глобалдыны көлеңкелейді
    print('Функциядағы жергілікті: $value');

    if (true) {
      int value = 300; // функцияның жергілікті айнымалысын көлеңкелейді
      print('if блогындағы жергілікті: $value');
    }

    print('if блогынан кейін: $value'); // қайтадан 200
  }

  complexExample();
  print('Глобалды әлі де: $value'); // қайтадан 100

  // Мысал 3: Бірдей атаулары бар параметрлер
  void calculate(int x, int y) {
    int result = x + y;
    print('$x + $y = $result');

    // Әрбір шақыру жаңа x, y, result жасайды
  }

  calculate(5, 3);
  calculate(10, 20);

  // Мысал 4: Анықтық үшін көлеңкелеуден аулақ болыңыз
  void goodExample(int number) { // түсінікті атау
    int globalValue = value; // глобалдыны айқын пайдалану
    print('Параметр: $number, Глобалды: $globalValue');
  }

  goodExample(42);
}

void main() {
  // Мысал 1: Сыртқы айнымалыларға қатынас
  int outerVar = 10;

  void innerFunction() {
    // Ішкі функция main айнымалыларын көреді
    print('Сыртқы айнымалы: $outerVar');
    outerVar = 20; // өзгерте аламыз!
  }

  innerFunction();
  print('Өзгерткеннен кейін: $outerVar'); // 20

  // Мысал 2: Ішкі аймақтардың тізбегі
  int level1 = 1;

  if (true) {
    int level2 = 2;
    print('Деңгей 2: level1=$level1, level2=$level2');

    if (true) {
      int level3 = 3;
      print('Деңгей 3: level1=$level1, level2=$level2, level3=$level3');

      // Сыртқы аймақтардың айнымалыларын өзгерте аламыз
      level1 = 10;
      level2 = 20;
    }

    print('Деңгей 3-тен кейін: level1=$level1, level2=$level2');
    // print(level3); // ҚАТЕ! level3 көрінбейді
  }

  // Мысал 3: Ішкі функциялар
  void outerFunction() {
    int x = 100;

    void middleFunction() {
      int y = 200;

      void innerFunction() {
        int z = 300;
        print('Барлығы көрінеді: x=$x, y=$y, z=$z');
      }

      innerFunction();
      // print(z); // ҚАТЕ! z көрінбейді
    }

    middleFunction();
    // print(y); // ҚАТЕ! y көрінбейді
  }

  outerFunction();
}

void main() {
  // Мысал 1: Базалық жабу
  Function makeAdder(int addBy) {
    // addBy - сыртқы аймақтағы айнымалы
    return (int value) {
      return value + addBy; // жабу addBy-ді "есте сақтады"!
    };
  }

  var add5 = makeAdder(5);
  var add10 = makeAdder(10);

  print('10 + 5 = ${add5(10)}');   // 15
  print('10 + 10 = ${add10(10)}'); // 20

  // Мысал 2: Жабумен санағыш (жеке айнымалы)
  Function makeCounter() {
    int count = 0; // "жеке" айнымалы

    return () {
      count++; // сыртқы аймақтағы айнымалыны өзгертеміз
      return count;
    };
  }

  var counter1 = makeCounter();
  var counter2 = makeCounter(); // тәуелсіз санағыш!

  print('Санағыш 1:');
  print(counter1()); // 1
  print(counter1()); // 2
  print(counter1()); // 3

  print('Санағыш 2:');
  print(counter2()); // 1
  print(counter2()); // 2

  // Мысал 3: Баптаумен көбейткіш
  Function createMultiplier(String name, int factor) {
    int callCount = 0;

    return (int value) {
      callCount++;
      int result = value * factor;
      print('$name $callCount рет шақырылды: $value × $factor = $result');
      return result;
    };
  }

  var double = createMultiplier('Екі еселегіш', 2);
  var triple = createMultiplier('Үш еселегіш', 3);

  double(5);
  double(10);
  triple(5);

  // Мысал 4: Циклдегі жабу (жиі қате)
  List<Function> functions = [];

  for (int i = 0; i < 3; i++) {
    functions.add(() => print('Функция $i'));
  }

  print('\nТізімнен функцияларды шақыру:');
  for (var func in functions) {
    func(); // Әр функция өзінің i мәнін "есте сақтады"
  }
}

